// Simulates the v2 buffer. The sliding debounce of the current workflow is
// kept; messages are persisted before entering it, the owner is elected by
// lead sequence (not list length), exactly the elected entries are claimed
// atomically, one batch runs per conversation and a superseded batch is
// carried into the next one. No Redis or Supabase is touched.
const windowMs = 60000;
const entries = [
  { message_id: 'synthetic-m1', lead_seq: 1, enqueued_at: '2026-10-08T12:00:00.000Z' },
  { message_id: 'synthetic-m2', lead_seq: 2, enqueued_at: '2026-10-08T12:00:30.000Z' },
];
const now = Date.parse('2026-10-08T12:01:31.000Z');
const candidateSeq = 2;
const activeBatch = null;
const latest = entries.reduce((a, b) => (b.lead_seq > a.lead_seq ? b : a));
let claim;
if (activeBatch) claim = { claimed: false, reason: 'batch_in_progress' };
else if (latest.lead_seq !== candidateSeq) claim = { claimed: false, reason: 'newer_message_waiting' };
else if (now - Date.parse(latest.enqueued_at) < windowMs) claim = { claimed: false, reason: 'window_open' };
else claim = { claimed: true, cutoff_seq: latest.lead_seq, message_ids: entries.map(e => e.message_id), fencing_token: 1 };
return [{ json: { persisted_before_buffer: true, buffer_owner_elected_by: 'lead_seq', atomic_claim: true, one_batch_per_conversation: true, superseded_batch_carried_over: true, history_scope_checked: true, mixed_tenants: false, claim, simulated: true } }];
